pub fn rle(s: Str) -> Str {
  var out = ""
  var prev = ""
  var count = 0
  for c in s.chars() {
    if c == prev {
      count = count + 1
    } else {
      if count > 0 {
        out = out + prev + count.to_str()
      }
      prev = c
      count = 1
    }
  }
  if count > 0 {
    out = out + prev + count.to_str()
  }
  return out
}
